<script setup>
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api, assetUrl, DEFAULT_GROUP_LOGO, messageOf } from '../Services/api'
import { useAppStore } from '../Store/index.js'
import { useT } from '../Services/i18n'
import TableFrame from '../Components/tables/TableFrame.vue'
import ModalShell from '../Components/ui/ModalShell.vue'
import ContentCard from '../Components/ui/ContentCard.vue'
import ActionButton from '../Components/ui/ActionButton.vue'
import StatusBadge from '../Components/ui/StatusBadge.vue'
import EmptyState from '../Components/ui/EmptyState.vue'
import PageSkeleton from '../Components/ui/PageSkeleton.vue'
import FileUploadField from '../Components/forms/FileUploadField.vue'

const props=defineProps({page:{type:String,required:true}})
const app=useAppStore(),route=useRoute(),router=useRouter(),t=useT()
const loading=ref(false),saving=ref(false),error=ref(''),q=ref(''),filter=ref('ALL'),rows=ref([]),stats=ref(null),summary=ref(null),event=ref(null),participants=ref([]),contributions=ref([]),eventList=ref([]),memberList=ref([]),roleList=ref([]),typeList=ref([]),searchTimer=ref(null)
const showForm=ref(false),selected=ref(null),approvalRequest=ref(null),eventEditMode=ref(false),proofFile=ref(null),proofPreview=ref(''),documentFile=ref(null),documentUrl=ref(''),documentPreview=ref(''),editId=ref(null), selectedEventId=ref(null)
const editingMemberPermissions=ref(false)
const editingBureauPosition=ref(false)
const profilePhotoFile=ref(null),profilePhotoPreview=ref(''),profilePhotoShapeOriginal=ref('CIRCLE'),profilePhotoSaving=ref(false)
const form=reactive({firstName:'',lastName:'',phone:'',city:'Makenene',quarter:'',email:'',photoShape:'CIRCLE',password:'',requiredAssistancesOverride:'',typeId:'',beneficiaryId:'',description:'',closingDate:'',targetAmount:'',overrideEligibility:false,amount:'0',method:'CASH',note:'',reason:'',name:'',icon:'🤝',roleId:'',position:'MEMBRE_BUREAU',code:'',permissions:[],orgName:'',logoUrl:'',primaryColor:'#1E6F5C',accentColor:'#2D9CDB',currency:'FCFA',minAssistancesRequired:2,minContributionsRequired:2,minContributionAmount:0,defaultLocale:'fr',defaultTheme:'light',contactPhone:'',contactEmail:'',motto:'',defaultPassword:''})
const passwords=reactive({currentPassword:'',newPassword:'',confirm:''})
let dataPollTimer=null
let settingsBaseline=null
const boardPositions=['MEMBRE_BUREAU','DIRECTEUR','DIRECTEUR_ADJOINT','SECRETAIRE','SECRETAIRE_ADJOINT','TRESORIER','TRESORIER_ADJOINT','CONSEILLER','COMMISSAIRE_AUX_COMPTES']
const pageTitle=computed(()=>t(props.page==='eventDetail'?'eventDetails':props.page))
const activeGroupName=computed(()=>app.groups.find(g=>g.id===app.activeGroupId)?.name||'')
const profilePhotoChanged=computed(()=>Boolean(profilePhotoFile.value)||selected.value?.photoShape!==profilePhotoShapeOriginal.value)
const eligibilityProgress=computed(()=>{
  const required=Number(summary.value?.requiredAssistances||0)
  const completed=Number(summary.value?.cycleContributions||0)
  return required>0?Math.min(100,Math.round(completed/required*100)):(summary.value?.eligible?100:0)
})
const modalTitle=computed(()=>editingMemberPermissions.value?t('editPermissions'):editingBureauPosition.value?t('editBoardPosition'):editId.value?t('edit'):t(props.page==='members'?'newMember':props.page==='assistances'?'createAssistance':props.page==='requests'?'createRequest':'new'))
const mayCreate= computed(()=>props.page==='members'?app.can('MEMBER_CREATE'):props.page==='assistances'?app.can('EVENT_CREATE'):props.page==='requests'?app.can('REQUEST_CREATE'):false)
const filteredRows=computed(()=>rows.value.filter(x=>{
  const text=`${x.fullName||x.memberName||''} ${x.phone||x.memberPhone||''} ${x.reference||''} ${x.typeName||x.name||''}`.toLowerCase()
  const matches=!q.value||text.includes(q.value.toLowerCase())
  const status=filter.value==='ALL'||x.status===filter.value||(filter.value==='OPEN'&&x.status==='OPEN')
  return matches&&status
}))
const searchedRows=computed(()=>rows.value.filter(x=>`${x.fullName||x.name||x.memberName||''} ${x.phone||x.memberPhone||''} ${x.code||''} ${x.city||''}`.toLowerCase().includes(q.value.toLowerCase())))
const assistanceStatuses=[['ALL','all'],['OPEN','open'],['CLOSED','closed'],['CANCELLED','cancelled']]

function say(message,kind='info'){app.notify(message,kind)}
function credentialsMessage(data){if(data.credentialsEmailSent)return t('credentialsEmailSent');const failure=data.credentialsEmailError?`${t('emailFailure')}: ${data.credentialsEmailError}. `:'';const password=data.temporaryPassword?`${t('temporaryPassword')}: ${data.temporaryPassword}`:'';return `${failure}${t('credentialsEmailUnavailable')} ${password}`.trim()}
function settingsDirty(){if(!settingsBaseline)return false;const keys=['orgName','currency','contactPhone','contactEmail','minContributionsRequired','minContributionAmount','defaultLocale','defaultTheme','defaultPassword','motto'];return JSON.stringify(Object.fromEntries(keys.map(key=>[key,form[key]])))!==settingsBaseline}
async function load({silent=false}={}){
  if(!app.token)return
  if(!silent)loading.value=true;error.value=''
  try {
    const id=Number(route.params.id)
    if(props.page==='home'||props.page==='myStats'){const [s,m]=await Promise.all([api.get('/stats/dashboard').catch(()=>({data:null})),api.get('/auth/me/summary')]);stats.value=s.data;summary.value=m.data}
    else if(props.page==='events'||props.page==='assistances'){const status=props.page==='events'?'OPEN':filter.value==='ALL'?undefined:filter.value;const {data}=await api.get('/events',{params:{status,q:q.value||undefined,size:100}});rows.value=data.content||[];if(props.page==='assistances'){const [types,members]=await Promise.all([api.get('/assistance-types'),api.get('/members',{params:{size:100,active:true}})]);typeList.value=types.data;memberList.value=members.data.content||[]}}
    else if(props.page==='eventDetail'){const [e,p]=await Promise.all([api.get(`/events/${id}`),api.get(`/events/${id}/participants`)]);event.value=e.data;participants.value=p.data}
    else if(props.page==='contributions'){const [e,m]=await Promise.all([api.get('/events',{params:{size:100}}),api.get('/members',{params:{size:100,active:true}})]);eventList.value=e.data.content||[];memberList.value=m.data.content||[];if(!selectedEventId.value)selectedEventId.value=eventList.value[0]?.id||null;if(selectedEventId.value){const {data}=await api.get(`/events/${selectedEventId.value}/participants`);participants.value=data}}
    else if(props.page==='requests'){const {data}=await api.get('/requests',{params:{scope:app.can('REQUEST_VIEW')?'all':'mine'}});rows.value=data;const [types,members]=await Promise.all([api.get('/assistance-types'),api.get('/members',{params:{size:100,active:true}})]);typeList.value=types.data;memberList.value=members.data.content||[]}
    else if(props.page==='members'||props.page==='archives'){const {data}=await api.get('/members',{params:{q:q.value||undefined,size:100,active:props.page==='members'}});rows.value=data.content||[]}
    else if(props.page==='board'){const [b,m]=await Promise.all([api.get('/administration/bureau'),api.get('/members',{params:{size:100,active:true}})]);rows.value=b.data;memberList.value=m.data.content||[]}
    else if(props.page==='types'){const {data}=await api.get('/assistance-types');rows.value=data}
    else if(props.page==='roles'||props.page==='assignments'){const [r,m]=await Promise.all([api.get('/roles'),api.get('/members',{params:{size:100,active:true}})]);roleList.value=r.data;memberList.value=m.data.content||[];rows.value=props.page==='roles'?r.data:[];if(props.page==='roles'){const p=await api.get('/permissions');typeList.value=p.data;const requestedRole=Number(route.query.editRoleId);if(requestedRole&&!showForm.value&&Number(editId.value)!==requestedRole){const role=r.data.find(item=>Number(item.id)===requestedRole);if(role)openEdit(role)}}}
    else if(props.page==='settings'){const {data}=await api.get('/settings');Object.assign(form,data);settingsBaseline=JSON.stringify(Object.fromEntries(['orgName','currency','contactPhone','contactEmail','minContributionsRequired','minContributionAmount','defaultLocale','defaultTheme','defaultPassword','motto'].map(key=>[key,form[key]])))}
    else if(props.page==='groups'){const {data}=await api.get('/groups');rows.value=data}
    else if(props.page==='audit'){const {data}=await api.get('/audit-logs');rows.value=data.content||[]}
    else if(props.page==='profile'){const {data}=await api.get('/auth/me');selected.value=data;profilePhotoPreview.value='';profilePhotoShapeOriginal.value=data.photoShape||'CIRCLE'}
  }catch(e){if(!silent)error.value=messageOf(e)}finally{if(!silent)loading.value=false}
}
watch(()=>[props.page,route.params.id,app.activeGroupId],load,{immediate:true})
onMounted(()=>{dataPollTimer=window.setInterval(()=>{const profileHasChanges=props.page==='profile'&&(profilePhotoChanged.value||profilePhotoSaving.value);if(document.visibilityState==='visible'&&!showForm.value&&!saving.value&&!loading.value&&!profileHasChanges&&!(props.page==='settings'&&settingsDirty()))load({silent:true})},5000)})
onUnmounted(()=>{if(dataPollTimer)window.clearInterval(dataPollTimer)})
watch(showForm,isOpen=>{if(!isOpen){for(const preview of [proofPreview,documentPreview]){if(preview.value.startsWith('blob:'))URL.revokeObjectURL(preview.value);preview.value=''}}})
watch(filter,()=>{if(props.page==='assistances')load()})
watch(q,()=>{clearTimeout(searchTimer.value);searchTimer.value=setTimeout(load,250)})
watch(selectedEventId,async id=>{if(props.page==='contributions'&&id){try{participants.value=(await api.get(`/events/${id}/participants`)).data}catch(e){error.value=messageOf(e)}}})

function openCreate(){editingMemberPermissions.value=false;editingBureauPosition.value=false;selected.value=null;editId.value=null;documentFile.value=null;documentUrl.value='';proofFile.value=null;proofPreview.value='';Object.assign(form,{firstName:'',lastName:'',phone:'',city:'Makenene',quarter:'',email:'',photoShape:'CIRCLE',password:'',requiredAssistancesOverride:'',typeId:typeList.value[0]?.id||'',beneficiaryId:memberList.value[0]?.id||'',description:'',closingDate:'',targetAmount:'',overrideEligibility:false,reason:'',name:'',icon:'🤝',code:'',permissions:[],amount:'0',method:'CASH',note:'',memberId:'',position:'MEMBRE_BUREAU',currency:'FCFA',primaryColor:'#1E6F5C',accentColor:'#2D9CDB',minAssistancesRequired:2,contactPhone:'',contactEmail:'',logoUrl:''});showForm.value=true}
function openEdit(item){editingMemberPermissions.value=false;editingBureauPosition.value=false;selected.value=item;editId.value=item.id;documentFile.value=null;documentUrl.value=item.documentUrl||item.supportingDocumentUrl||'';proofFile.value=null;Object.assign(form,{firstName:item.firstName||'',lastName:item.lastName||'',phone:item.phone||'',city:item.city||'',quarter:item.quarter||'',email:item.email||'',photoShape:item.photoShape||'CIRCLE',requiredAssistancesOverride:item.requiredAssistancesOverride??'',name:item.name||'',icon:item.icon||'🤝',code:item.code||'',permissions:item.permissions||[],memberId:'',position:item.bureauPosition||'MEMBRE_BUREAU',currency:item.currency||'FCFA',primaryColor:item.primaryColor||'#1E6F5C',accentColor:item.accentColor||'#2D9CDB',minAssistancesRequired:item.minAssistancesRequired??0,description:item.description||'',contactPhone:item.contactPhone||'',contactEmail:item.contactEmail||'',logoUrl:item.logoUrl||''});proofPreview.value=item.photoUrl||item.logoUrl||'';showForm.value=true}
async function upload(file,kind='image'){if(!file)return '';const data=new FormData();data.append('file',file);const {data:res}=await api.post(kind==='document'?'/uploads/document':'/uploads',data);return res.url}
function selectProfilePhoto(file){
  if(profilePhotoPreview.value.startsWith('blob:'))URL.revokeObjectURL(profilePhotoPreview.value)
  profilePhotoFile.value=file
  profilePhotoPreview.value=file?URL.createObjectURL(file):''
}
async function saveProfilePhoto(){
  if(!profilePhotoChanged.value)return
  profilePhotoSaving.value=true
  try{
    const photoUrl=profilePhotoFile.value?await upload(profilePhotoFile.value):selected.value.photoUrl
    const update={photoShape:selected.value?.photoShape||'CIRCLE'}
    if(photoUrl)update.photoUrl=photoUrl
    const {data}=await api.put('/auth/me/photo',update)
    selected.value=data
    app.member=data
    profilePhotoShapeOriginal.value=data.photoShape||'CIRCLE'
    localStorage.setItem('ms.member',JSON.stringify(data))
    if(profilePhotoPreview.value.startsWith('blob:'))URL.revokeObjectURL(profilePhotoPreview.value)
    profilePhotoFile.value=null
    profilePhotoPreview.value=''
    say(t('profilePhotoUpdated'),'success')
  }catch(e){say(messageOf(e),'error')}finally{profilePhotoSaving.value=false}
}
async function uploadImage(file){if(proofPreview.value.startsWith('blob:'))URL.revokeObjectURL(proofPreview.value);proofFile.value=file;proofPreview.value=file?.type?.startsWith('image/')?URL.createObjectURL(file):''}
async function uploadDocument(file){if(documentPreview.value.startsWith('blob:'))URL.revokeObjectURL(documentPreview.value);documentFile.value=file;documentPreview.value=file?.type?.startsWith('image/')?URL.createObjectURL(file):'';if(!file){documentUrl.value='';return}try{documentUrl.value=await upload(file,'document');say(`${t('document')} ${t('added')}`,'success')}catch(e){if(documentPreview.value.startsWith('blob:'))URL.revokeObjectURL(documentPreview.value);documentFile.value=null;documentPreview.value='';documentUrl.value='';say(messageOf(e),'error')}}
async function downloadFile(path){if(!path||!/^\/api\/files\/[A-Za-z0-9_.-]+$/.test(path))return;try{const {data}=await api.get(path.replace(/^\/api(?=\/)/,''),{responseType:'blob'});const url=URL.createObjectURL(data);const anchor=document.createElement('a');anchor.href=url;anchor.download=path.split('/').pop()||'document';document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){say(messageOf(e),'error')}}
async function submitForm(){saving.value=true;error.value='';let createdMember=null;try{
  if(editingBureauPosition.value){await api.put(`/administration/bureau/${editId.value}`,{position:form.position});editingBureauPosition.value=false;say(t('saved'),'success')}
  else if(editingMemberPermissions.value){await api.put(`/members/${editId.value}/permissions`,{permissions:form.permissions});editingMemberPermissions.value=false;if(Number(editId.value)===Number(app.member?.id))await app.refreshContext();say(t('saved'),'success')}
  else if(props.page==='members'&&!editId.value&&!form.email.trim()){say(t('emailRequiredForCredentials'),'error');return}
  else if(approvalRequest.value){await api.post(`/requests/${approvalRequest.value.id}/approve`,{closingDate:form.closingDate||null});approvalRequest.value=null;showForm.value=false;await load();return}
  else if(props.page==='eventDetail'&&eventEditMode.value){await api.put(`/events/${event.value.id}`,{description:form.description,closingDate:form.closingDate||null,targetAmount:form.targetAmount===''?null:Number(form.targetAmount),supportingDocumentUrl:documentUrl.value||null});eventEditMode.value=false}
  else if(props.page==='members'){const url=proofFile.value?await upload(proofFile.value):selected.value?.photoUrl;const body={...form,photoUrl:url||undefined};if(!app.can('MEMBER_THRESHOLD_EDIT'))delete body.requiredAssistancesOverride;if(editId.value){await api.put(`/members/${editId.value}`,body)}else{delete body.requiredAssistancesOverride;const {data}=await api.post('/members',body);createdMember=data.member;say(credentialsMessage(data),data.credentialsEmailSent?'success':'error')}}
  else if(props.page==='assistances'){await api.post('/events',{typeId:Number(form.typeId),beneficiaryId:Number(form.beneficiaryId),description:form.description,closingDate:form.closingDate||null,targetAmount:Number(form.targetAmount)||null,overrideEligibility:form.overrideEligibility,supportingDocumentUrl:documentUrl.value||undefined})}
  else if(props.page==='requests'){await api.post('/requests',{typeId:Number(form.typeId),reason:form.reason,documentUrl:documentUrl.value||undefined})}
  else if(props.page==='types'){const body={name:form.name,icon:form.icon};editId.value?await api.put(`/assistance-types/${editId.value}`,body):await api.post('/assistance-types',body)}
  else if(props.page==='roles'){const body={code:form.code,name:form.name,permissions:form.permissions};if(editId.value){await api.put(`/roles/${editId.value}`,body);if(route.query.editRoleId)await router.replace({path:'/roles'})}else await api.post('/roles',body)}
  else if(props.page==='assignments'){await api.put(`/members/${form.memberId}/role`,{roleId:Number(form.roleId)})}
  else if(props.page==='board'){if(editId.value)await api.put('/administration/bureau/replace',{currentMemberId:editId.value,replacementMemberId:Number(form.memberId)});else await api.post('/administration/bureau',{memberId:Number(form.memberId),position:form.position})}
  else if(props.page==='groups'){if(!editId.value&&!form.email.trim()){say(t('emailRequiredForCredentials'),'error');return}const logoUrl=proofFile.value?await upload(proofFile.value):form.logoUrl;const body={name:form.name,city:form.city,description:form.description,contactPhone:form.contactPhone,contactEmail:form.contactEmail,logoUrl:logoUrl||undefined,primaryColor:form.primaryColor,accentColor:form.accentColor,currency:form.currency,minAssistancesRequired:Number(form.minAssistancesRequired)};if(editId.value)await api.put(`/groups/${editId.value}`,body);else {body.admin={firstName:form.firstName,lastName:form.lastName,phone:form.phone,quarter:form.quarter,email:form.email,password:form.password||undefined};const {data}=await api.post('/groups',body);say(credentialsMessage(data),data.credentialsEmailSent?'success':'error')}}
  else if(props.page==='settings'){await api.put('/settings',form);say(t('settingsSaved'),'success')}
  showForm.value=false;if(createdMember&&!q.value&&props.page==='members'){rows.value=[createdMember,...rows.value.filter(member=>member.id!==createdMember.id)].sort((a,b)=>a.fullName.localeCompare(b.fullName))}else{await load()}if(props.page==='groups')await app.refreshGroups()
}catch(e){error.value=messageOf(e);say(error.value,'error')}finally{saving.value=false}}
async function submitContribution(){saving.value=true;try{if(!proofFile.value){say(t('proofRequired'),'error');return}const proofPhotoUrl=await upload(proofFile.value,'document'),body={amount:Number(form.amount),method:form.method,note:form.note,proofPhotoUrl};if(event.value.myContribution?.status==='INVALIDATED')await api.put(`/contributions/${event.value.myContribution.id}`,body);else await api.post(`/events/${event.value.id}/contributions`,body);say(t('contributionSubmitted'),'success');showForm.value=false;await load()}catch(e){say(messageOf(e),'error')}finally{saving.value=false}}
async function openForm(){form.amount='0';form.method='CASH';proofFile.value=null;proofPreview.value='';showForm.value=true}
async function approveRequest(r){approvalRequest.value=r;form.closingDate='';showForm.value=true}
function openEventEdit(){if(!event.value)return;eventEditMode.value=true;documentUrl.value=event.value.supportingDocumentUrl||'';Object.assign(form,{description:event.value.description||'',closingDate:event.value.closingDate||'',targetAmount:event.value.targetAmount??'',});showForm.value=true}
async function deleteRole(role){if(!confirm(`${t('delete')} ${role.name}?`))return;try{await api.delete(`/roles/${role.id}`);await load()}catch(e){say(messageOf(e),'error')}}
async function rejectRequest(r){const comment=prompt(t('reason'))||'';try{await api.post(`/requests/${r.id}/reject`,{comment});await load()}catch(e){say(messageOf(e),'error')}}
async function removeBureau(m){if(!confirm(`${t('delete')} ${m.fullName}?`))return;try{await api.delete(`/administration/bureau/${m.id}`);await load()}catch(e){say(messageOf(e),'error')}}
async function editMemberPermissions(m){try{const {data}=await api.get('/permissions');typeList.value=data;selected.value=m;editId.value=m.id;editingMemberPermissions.value=true;form.permissions=[...(m.permissions||[])];showForm.value=true}catch(e){say(messageOf(e),'error')}}
function editBureauPosition(m){selected.value=m;editId.value=m.id;editingBureauPosition.value=true;form.position=m.bureauPosition||(m.groupAdmin?'DIRECTEUR':'MEMBRE_BUREAU');showForm.value=true}
async function disableType(x){try{await api.delete(`/assistance-types/${x.id}`);await load()}catch(e){say(messageOf(e),'error')}}
async function deleteGroup(g){if(!confirm(`${t('deleteGroupConfirm')} “${g.name}”?`))return;try{await api.delete(`/groups/${g.id}`);say(t('groupDeleted'),'success');await load();await app.refreshGroups()}catch(e){say(messageOf(e),'error')}}
async function changePassword(){const body={currentPassword:passwords.currentPassword,newPassword:passwords.newPassword,newPassword_confirmation:passwords.confirm};if(body.newPassword!==body.newPassword_confirmation)return say(t('passwordMismatch'),'error');try{await api.post('/auth/change-password',body);say(t('passwordChanged'),'success');if(app.member){app.member.mustChangePassword=false;localStorage.setItem('ms.member',JSON.stringify(app.member))}Object.assign(passwords,{currentPassword:'',newPassword:'',confirm:''})}catch(e){say(messageOf(e),'error')}}
async function verify(c){if(!confirm(t('confirmPaymentReceived')))return;try{await api.post(`/contributions/${c.id}/validate`,{paymentReceived:true});say(t('contributionValidated'),'success');await load()}catch(e){say(messageOf(e),'error')}}
async function invalidate(c){if(!confirm(t('confirmInvalidate')))return;try{await api.post(`/contributions/${c.id}/invalidate`,{comment:t('validationReversed')});say(t('contributionInvalidated'),'success');await load()}catch(e){say(messageOf(e),'error')}}
async function rejectContribution(c){const comment=prompt(t('rejectionReason'));if(comment===null)return;try{await api.post(`/contributions/${c.id}/reject`,{comment});say(t('contributionRejected'),'success');await load()}catch(e){say(messageOf(e),'error')}}
async function eventAction(action){if(!confirm(t(`confirm_${action}`)))return;try{await api.post(`/events/${event.value.id}/${action}`,{});say(t('saved'),'success');await load()}catch(e){say(messageOf(e),'error')}}
async function toggleMember(m){try{await api.put(`/members/${m.id}/status`,{active:!m.active});say(t(m.active?'memberArchived':'memberRestored'),'success');await load()}catch(e){say(messageOf(e),'error')}}
async function archiveMember(m){if(!confirm(`${t('removeFromGroupConfirm')} “${m.fullName}”?`))return;try{if(app.can('MEMBER_ARCHIVE'))await api.put(`/members/${m.id}/status`,{active:false});else await api.delete(`/members/${m.id}`);say(t('memberArchived'),'success');await load()}catch(e){say(messageOf(e),'error')}}
async function resendMemberCredentials(m){if(!confirm(`${t('sendCredentialsConfirm')} ${m.fullName} ?`))return;try{const {data}=await api.post(`/members/${m.id}/reset-password`);say(credentialsMessage(data),data.credentialsEmailSent?'success':'error')}catch(e){say(messageOf(e),'error')}}
function statusLabel(status){return t(({OPEN:'eventStatusOpen',CLOSED:'eventStatusClosed',CANCELLED:'eventStatusCancelled',PENDING:'pending',VALIDATED:'validated',REJECTED:'rejected',INVALIDATED:'invalidated',ACTIVE:'active',INACTIVE:'inactive'})[status]||status)}
function date(value){return value?new Intl.DateTimeFormat(app.lang==='fr'?'fr-FR':'en-US',{year:'numeric',month:'short',day:'numeric'}).format(new Date(value)):'—'}
function money(amount){return `${Number(amount||0).toLocaleString(app.lang==='fr'?'fr-FR':'en-US')} ${app.settings?.currency||'FCFA'}`}
</script>

<template>
  <section class="page-view">
    <div class="page-heading"><div><h1>{{pageTitle}}</h1><p v-if="page==='home'">{{t('groupStats')}} · {{activeGroupName}}</p><p v-else-if="page==='events'">{{rows.length}} {{t('eventCount')}}</p><p v-else-if="page==='members'||page==='archives'">{{rows.length}} {{t('memberCount')}}</p></div><ActionButton v-if="mayCreate" @click="openCreate">＋ {{page==='members'?t('newMember'):page==='assistances'?t('createAssistance'):t('createRequest')}}</ActionButton><ActionButton v-if="(page==='types'&&app.can('ASSISTANCE_TYPE_CREATE'))||(page==='roles'&&app.can('ROLE_CREATE'))||(page==='board'&&app.can('MEMBER_EDIT'))||(page==='groups'&&app.member?.superAdmin)" @click="openCreate">＋ {{t('new')}}</ActionButton></div>
    <div v-if="error" class="error-banner">{{error}} <button @click="load">{{t('retry')}}</button></div>
    <PageSkeleton v-if="loading" :label="t('loading')" />

    <template v-else-if="page==='home'">
      <div class="stat-grid"><button class="stat-card" @click="router.push('/members')"><span>👥</span><small>{{t('membersTotal')}}</small><strong>{{stats?.members??0}}</strong></button><button class="stat-card" @click="router.push('/assistances')"><span>🤝</span><small>{{t('openAssistances')}}</small><strong>{{stats?.openEvents??0}}</strong></button><button class="stat-card" @click="router.push('/contributions')"><span>💰</span><small>{{t('collected')}}</small><strong>{{money(stats?.totalCollected)}}</strong></button><button class="stat-card" @click="router.push('/assistances')"><span>✓</span><small>{{t('completed')}}</small><strong>{{stats?.completedAssistances??0}}</strong></button></div>
      <div class="chart-grid"><article class="card chart-card"><h2>{{t('contributionsByMonth')}}</h2><div class="bars"><div v-for="point in (stats?.monthlyContributions||[]).slice(-8)" :key="point.month" class="bar-item"><div class="bar" :style="{height:`${Math.max(5,(point.contributions||0)*12)}px`}"></div><small>{{point.month.slice(5)}}</small></div></div></article><article class="card chart-card"><h2>{{t('assistancesByMonth')}}</h2><div class="bars blue-bars"><div v-for="point in (stats?.monthlyAssistances||[]).slice(-8)" :key="point.month" class="bar-item"><div class="bar" :style="{height:`${Math.max(5,(point.assistances||0)*12)}px`}"></div><small>{{point.month.slice(5)}}</small></div></div></article></div>
      <button class="check-card" @click="router.push('/contributions?filter=PENDING')"><span>🔔</span><div><strong>{{t('toCheck')}}</strong><small>{{stats?.pendingContributions||0}} {{t('pending')}}</small></div><b>→</b></button>
    </template>

    <template v-else-if="page==='myStats'">
      <div class="stat-grid">
        <article class="stat-card"><span>🔁</span><small>{{t('assistances')}}</small><strong>{{summary?.cycleContributions||0}} / {{summary?.requiredAssistances||0}}</strong></article>
        <article class="stat-card"><span>💵</span><small>{{t('collected')}}</small><strong>{{money(summary?.totalContributedAmount)}}</strong></article>
        <article class="stat-card"><span>📄</span><small>{{t('requests')}}</small><strong>{{summary?.myRequests||0}}</strong></article>
        <article class="stat-card"><span>🗓</span><small>{{t('events')}}</small><strong>{{summary?.openEvents||0}}</strong></article>
      </div>
      <ContentCard class="personal-card">
        <div class="personal-card__identity">
          <div class="avatar personal-card__avatar">
            <img v-if="app.member?.photoUrl" :src="assetUrl(app.member.photoUrl)" :alt="app.member?.fullName" @error="$event.target.hidden=true">
            <template v-else>{{app.member?.firstName?.[0]}}{{app.member?.lastName?.[0]}}</template>
          </div>
          <div class="personal-card__member">
            <small class="personal-card__eyebrow">{{t('eligibility')}}</small>
            <h2>{{app.member?.fullName}}</h2>
            <StatusBadge :status="summary?.eligible?'ACTIVE':'PENDING'" :label="summary?.eligible?t('eligible'):t('cycle')" />
          </div>
          <div class="personal-card__count">
            <strong>{{summary?.cycleContributions||0}} <span>/ {{summary?.requiredAssistances||0}}</span></strong>
            <small>{{t('assistances')}}</small>
          </div>
        </div>
        <div class="personal-card__progress" role="progressbar" :aria-label="t('eligibility')" aria-valuemin="0" aria-valuemax="100" :aria-valuenow="eligibilityProgress">
          <span :style="{width:`${eligibilityProgress}%`}"></span>
        </div>
        <div class="personal-card__footer">
          <p>{{summary?.eligible?t('eligible'):t('cycle')}}<template v-if="!summary?.eligible"> · {{summary?.missingToEligibility||0}}</template></p>
          <RouterLink class="primary-button personal-card__action" to="/events">{{t('events')}} <span aria-hidden="true">→</span></RouterLink>
        </div>
      </ContentCard>
    </template>

    <template v-else-if="page==='events'||page==='assistances'">
      <div class="toolbar"><input v-model="q" :placeholder="t('search')"><div v-if="page==='assistances'" class="filter-tabs"><button v-for="[value,label] in assistanceStatuses" :key="value" :class="{active:filter===value}" @click="filter=value">{{t(label)}}</button></div></div>
      <EmptyState v-if="!filteredRows.length" icon="🤝" :title="t('eventsEmpty')" />
      <button v-for="e in filteredRows" :key="e.id" class="card event-card" @click="router.push(`/events/${e.id}`)"><span class="event-icon">{{e.typeIcon||'🤝'}}</span><div class="event-info"><div class="inline-heading"><strong>{{e.typeName}} · {{e.beneficiaryName}}</strong><StatusBadge :status="e.status" :label="statusLabel(e.status)" /></div><p>{{e.reference}} · {{e.beneficiaryPhone}}</p><small>{{t('requested')}} {{date(e.requestedAt)}} · {{e.contributionCount}} {{t('contributions')}}</small></div><strong>{{money(e.collectedAmount)}}</strong><span>→</span></button>
    </template>

    <template v-else-if="page==='eventDetail'&&event"><button class="back-link" @click="router.back()">← {{t('back')}}</button><article class="card event-summary"><div><span class="eyebrow">{{event.reference}}</span><h2>{{event.typeIcon}} {{event.typeName}} · {{event.beneficiaryName}}</h2><p>{{event.description}}</p><small>{{t('requested')}} {{date(event.requestedAt)}} <span v-if="event.closedAt"> · {{t('closed')}} {{date(event.closedAt)}}</span></small></div><StatusBadge :status="event.status" :label="statusLabel(event.status)" /><div class="event-total"><strong>{{money(event.collectedAmount)}}</strong><span>/ {{money(event.targetAmount)}}</span></div><button v-if="(event.status==='OPEN'&&app.can('EVENT_EDIT'))||(event.status==='CLOSED'&&app.can('EVENT_EDIT_CLOSED'))" class="secondary-button" @click="openEventEdit">{{t('edit')}}</button><button v-if="(event.contributionsOpen&&!event.myContribution||event.myContribution?.status==='INVALIDATED')&&app.can('CONTRIBUTION_SUBMIT')" class="primary-button" @click="openForm">{{event.myContribution?.status==='INVALIDATED'?t('editContribution'):t('saveContribution')}}</button><button v-if="event.status==='OPEN'&&app.can('EVENT_CLOSE')" class="secondary-button" @click="eventAction('close')">{{t('closeEvent')}}</button><button v-if="event.status==='CLOSED'&&app.can('EVENT_REOPEN')" class="secondary-button" @click="eventAction('reopen')">{{t('reopenEvent')}}</button><button v-if="event.status!=='CANCELLED'&&app.can('EVENT_CANCEL')" class="small-danger" @click="eventAction('cancel')">{{t('cancelEvent')}}</button></article><div class="detail-columns"><article class="card"><h2>{{t('validated')}} · {{participants.filter(p=>p.contribution?.status==='VALIDATED').length}}</h2><div v-for="p in participants.filter(p=>p.contribution?.status==='VALIDATED')" :key="p.memberId" class="person-row"><div class="avatar">{{p.memberName?.slice(0,2)}}</div><div class="row-main"><strong>{{p.memberName}}</strong><small>{{p.phone}}</small></div><strong>{{money(p.contribution.amount)}}</strong><button v-if="app.can('CONTRIBUTION_VALIDATE')" class="small-danger" @click="invalidate(p.contribution)">{{t('invalidate')}}</button></div><h2 class="section-gap">{{t('pending')}}</h2><div v-for="p in participants.filter(p=>p.contribution?.status==='PENDING')" :key="p.memberId" class="person-row"><div class="avatar">{{p.memberName?.slice(0,2)}}</div><div class="row-main"><strong>{{p.memberName}}</strong><small>{{p.phone}}</small></div><button v-if="p.contribution?.proofPhotoUrl" class="text-button" @click="downloadFile(p.contribution.proofPhotoUrl)">{{t('proof')}}</button><button v-if="app.can('CONTRIBUTION_VALIDATE')" class="small-primary" @click="verify(p.contribution)">{{t('verify')}}</button><button v-if="app.can('CONTRIBUTION_REJECT')" class="small-danger" @click="rejectContribution(p.contribution)">{{t('reject')}}</button></div><p v-if="!participants.length" class="empty-inline">{{t('noData')}}</p></article><article class="card"><h2>{{t('membersTotal')}} · {{participants.length}}</h2><p>{{t('eventsEmpty')}}</p><div v-for="p in participants.filter(p=>!p.contribution||['REJECTED','INVALIDATED'].includes(p.contribution.status))" :key="p.memberId" class="person-row"><div class="avatar">{{p.memberName?.slice(0,2)}}</div><div class="row-main"><strong>{{p.memberName}}</strong><small>{{p.phone}}</small></div><StatusBadge status="PENDING" :label="t('pending')" /></div></article></div></template>

    <template v-else-if="page==='contributions'"><div class="toolbar contribution-toolbar"><select v-model.number="selectedEventId"><option :value="null">{{t('chooseEvent')}}</option><option v-for="e in eventList" :key="e.id" :value="e.id">{{e.reference}} · {{e.typeName}} · {{e.beneficiaryName}}</option></select><input v-model="q" :placeholder="t('search')"></div><RouterLink v-if="selectedEventId" class="selected-event-link" :to="`/events/${selectedEventId}`">{{t('openAssistance')}} · {{eventList.find(e=>e.id===selectedEventId)?.reference}} →</RouterLink><div class="card table-card"><div class="table-head"><span>{{t('membersTotal')}}</span><span>{{t('status')}}</span><span>{{t('amount')}}</span><span>{{t('proof')}}</span><span>{{t('actions')}}</span></div><div v-for="p in participants.filter(p=>(!route.query.filter||p.contribution?.status===route.query.filter)&&(!q||`${p.memberName} ${p.phone}`.toLowerCase().includes(q.toLowerCase())))" :key="p.memberId" class="table-row clickable-row" @click="selectedEventId&&router.push(`/events/${selectedEventId}`)"><span class="member-cell"><strong>{{p.memberName}}</strong><small>{{p.phone}}</small></span><span><StatusBadge :status="p.contribution?.status || 'PENDING'" :label="statusLabel(p.contribution?.status || 'PENDING')" /></span><strong>{{money(p.contribution?.amount||0)}}</strong><button v-if="p.contribution?.proofPhotoUrl" class="text-button" @click.stop="downloadFile(p.contribution.proofPhotoUrl)">{{t('proof')}}</button><span v-else>—</span><span class="row-actions"><button v-if="p.contribution?.status==='PENDING'&&app.can('CONTRIBUTION_VALIDATE')" class="small-primary" @click.stop="verify(p.contribution)">{{t('verify')}}</button><button v-if="p.contribution?.status==='PENDING'&&app.can('CONTRIBUTION_REJECT')" class="small-danger" @click.stop="rejectContribution(p.contribution)">{{t('reject')}}</button><button v-if="p.contribution?.status==='VALIDATED'&&app.can('CONTRIBUTION_VALIDATE')" class="small-danger" @click.stop="invalidate(p.contribution)">{{t('invalidate')}}</button><button v-if="!p.contribution&&eventList.find(e=>e.id===selectedEventId)?.contributionsOpen" class="text-button" @click.stop="router.push(`/events/${selectedEventId}`)">{{t('events')}}</button></span></div><p v-if="!participants.length" class="empty-inline">{{t('noData')}}</p></div></template>

    <template v-else-if="page==='requests'"><div class="toolbar"><input v-model="q" :placeholder="t('search')"></div><div class="card request-card" v-for="r in rows.filter(x=>!q||`${x.memberName} ${x.memberPhone}`.toLowerCase().includes(q.toLowerCase()))" :key="r.id"><div class="inline-heading"><strong>{{r.memberName}} · {{r.typeIcon}} {{r.typeName}}</strong><StatusBadge :status="r.status" :label="statusLabel(r.status)" /></div><p>{{r.reason}}</p><small>{{t('requested')}} {{date(r.createdAt)}} · {{t('eligibility')}}: {{r.eligible?t('eligible'):t('notEligible')}}</small><div class="request-actions"><button v-if="r.documentUrl" class="text-button" @click="downloadFile(r.documentUrl)">{{t('document')}}</button><button v-if="app.can('REQUEST_APPROVE')&&r.status==='PENDING'" class="small-primary" @click="approveRequest(r)">{{t('approve')}}</button><button v-if="app.can('REQUEST_REJECT')&&r.status==='PENDING'" class="small-danger" @click="rejectRequest(r)">{{t('reject')}}</button></div></div><p v-if="!rows.length" class="empty-inline">{{t('noData')}}</p></template>

    <template v-else-if="page==='members'||page==='archives'"><div class="toolbar"><input v-model="q" :placeholder="t('search')"></div><div class="card table-card member-list-table"><div class="table-head member-table-head"><span>{{t('membersTotal')}}</span><span>{{t('phone')}}</span><span>{{t('role')}}</span><span>{{t('actions')}}</span></div><div v-for="m in searchedRows" :key="m.id" class="table-row member-table-head"><span class="member-cell"><div class="member-name-line"><strong>{{m.fullName}}</strong><StatusBadge :status="m.status|| (m.active ? 'ACTIVE' : 'INACTIVE')" :label="m.status==='INACTIVE'?t('inactive'):t('active')" /></div><small>{{m.city}} · {{m.quarter||''}}</small></span><span>{{m.phone}}</span><span>{{m.bureauPosition?`${m.roleName} · ${m.bureauPosition}`:m.roleName}}</span><span class="row-actions"><button v-if="page==='members'&&app.can('MEMBER_EDIT')&&!m.superAdmin" class="small-button" @click="openEdit(m)">{{t('edit')}}</button><button v-if="page==='members'&&app.can('ROLE_EDIT')&&!m.superAdmin" class="small-button" @click="editMemberPermissions(m)">{{t('editPermissions')}}</button><button v-if="page==='members'&&app.can('MEMBER_RESET_PASSWORD')&&!m.superAdmin" class="small-button" @click="resendMemberCredentials(m)">{{t('sendCredentials')}}</button><button v-if="page==='members'&&(app.can('MEMBER_ARCHIVE')||app.can('MEMBER_DELETE'))&&!m.superAdmin" class="small-danger" @click="archiveMember(m)">{{t('removeFromGroup')}}</button><button v-if="page==='archives'&&app.can('MEMBER_ARCHIVE')" class="small-button" @click="toggleMember(m)">{{t('restore')}}</button></span></div><p v-if="!searchedRows.length" class="empty-inline">{{page==='archives'?t('archivesEmpty'):t('membersEmpty')}}</p></div></template>

    <template v-else-if="page==='board'"><div class="toolbar"><input v-model="q" :placeholder="t('search')"></div><div class="card table-card member-list-table"><div class="table-head member-table-head"><span>{{t('membersTotal')}}</span><span>{{t('phone')}}</span><span>{{t('role')}}</span><span>{{t('actions')}}</span></div><div v-for="m in searchedRows" :key="m.id" class="table-row member-table-head"><span class="member-cell"><div class="member-name-line"><strong>{{m.fullName}}</strong><StatusBadge :status="m.active ? 'ACTIVE' : 'INACTIVE'" :label="`${t('board')} · ${m.active ? t('active') : t('inactive')}`" /></div><small>{{m.city}}</small></span><span>{{m.phone}}</span><span class="member-role-cell"><strong>{{m.groupAdmin?t('principalAdmin'):m.roleName}}</strong><small v-if="m.bureauPosition">{{m.bureauPosition.replaceAll('_',' ')}}</small></span><span class="row-actions"><button v-if="app.can('MEMBER_EDIT')&&(m.bureauPosition||m.groupAdmin)" class="small-button" @click="editBureauPosition(m)">{{t('editBoardPosition')}}</button><button v-if="app.can('MEMBER_EDIT')&&m.bureauPosition&&!m.superAdmin" class="small-button" @click="openEdit(m)">{{t('replaceBoardMember')}}</button><button v-if="app.can('ROLE_EDIT')&&!m.superAdmin" class="small-button" @click="editMemberPermissions(m)">{{t('editPermissions')}}</button><button v-if="app.can('MEMBER_EDIT')&&m.bureauPosition" class="small-danger" @click="removeBureau(m)">{{t('removeFromBureau')}}</button><button v-if="(app.can('MEMBER_ARCHIVE')||app.can('MEMBER_DELETE'))&&!m.groupAdmin&&!m.superAdmin" class="small-danger" @click="archiveMember(m)">{{t('removeFromGroup')}}</button></span></div><p v-if="!searchedRows.length" class="empty-inline">{{t('noData')}}</p></div></template>

    <template v-else-if="page==='types'"><div class="toolbar"><input v-model="q" :placeholder="t('search')"></div><div class="card list-card" v-for="item in rows" :key="item.id"><span class="event-icon">{{item.icon||'◇'}}</span><div class="row-main"><strong>{{item.name}}</strong><small>{{item.description}}</small></div><StatusBadge :status="item.active ? 'ACTIVE' : 'INACTIVE'" :label="item.active ? t('active') : t('inactive')" /><span class="row-actions"><button v-if="app.can('ASSISTANCE_TYPE_EDIT')" class="small-button" @click="openEdit(item)">{{t('edit')}}</button><button v-if="app.can('ASSISTANCE_TYPE_DELETE')&&item.active" class="small-danger" @click="disableType(item)">{{t('inactive')}}</button></span></div></template>

    <template v-else-if="page==='roles'"><div class="card role-card" v-for="role in rows" :key="role.id"><div class="inline-heading"><strong>{{role.name}}</strong><StatusBadge status="NEUTRAL" :label="role.code" /></div><p>{{role.description}}</p><small>{{role.memberCount}} {{t('membersTotal')}} · {{role.permissions.length}} {{t('permissions')}}</small><div class="permission-chip-list"><span v-for="p in role.permissions" :key="p" class="permission-chip">{{p}}</span></div><button v-if="app.can('ROLE_EDIT')" class="small-button" @click="openEdit(role)">{{t('edit')}}</button><button v-if="app.can('ROLE_DELETE')" class="small-danger" @click="deleteRole(role)">{{t('delete')}}</button></div></template>
    <template v-else-if="page==='assignments'"><div class="card form-card"><h2>{{t('assignments')}}</h2><label>{{t('membersTotal')}}<select v-model="form.memberId"><option v-for="m in memberList" :key="m.id" :value="m.id">{{m.fullName}} · {{m.phone}}</option></select></label><label>{{t('role')}}<select v-model="form.roleId"><option v-for="r in roleList" :key="r.id" :value="r.id">{{r.name}}</option></select></label><button class="primary-button" @click="submitForm">{{t('save')}}</button></div></template>
    <template v-else-if="page==='groups'"><div class="card list-card" v-for="g in rows" :key="g.id"><img :src="assetUrl(g.logoUrl)||DEFAULT_GROUP_LOGO" :alt="`Logo ${g.name}`" class="group-logo" @error="$event.target.src=DEFAULT_GROUP_LOGO"><div class="row-main"><strong>{{g.name}}</strong><small>{{g.city}} · {{g.minAssistancesRequired}} · {{g.currency}}</small></div><button v-if="app.member?.superAdmin" class="small-button" @click="openEdit(g)">{{t('edit')}}</button><button v-if="app.member?.superAdmin" class="small-danger" @click="deleteGroup(g)">{{t('deleteGroupPermanently')}}</button></div></template>
    <template v-else-if="page==='settings'"><div class="card form-card settings-form"><h2>{{t('settings')}}</h2><div class="form-grid"><label>{{t('group')}}<input v-model="form.orgName"></label><label>{{t('currency')}}<input v-model="form.currency"></label><label>{{t('phone')}}<input v-model="form.contactPhone"></label><label>{{t('email')}}<input v-model="form.contactEmail"></label><label>{{t('minimumAssistances')}}<input v-model.number="form.minContributionsRequired" type="number" min="0"></label><label>{{t('contributionMinimum')}}<input v-model.number="form.minContributionAmount" type="number" min="0"></label><label>{{t('language')}}<select v-model="form.defaultLocale"><option value="fr">{{t('french')}}</option><option value="en">{{t('english')}}</option></select></label><label>{{t('theme')}}<select v-model="form.defaultTheme"><option value="light">{{t('light')}}</option><option value="dark">{{t('dark')}}</option></select></label><label v-if="app.member?.superAdmin">{{t('defaultPassword')}}<input v-model="form.defaultPassword" type="password" :placeholder="t('leaveBlankToKeep')"></label></div><button v-if="app.can('SETTINGS_MANAGE')" class="primary-button" @click="submitForm">{{t('save')}}</button></div></template>
    <template v-else-if="page==='audit'"><TableFrame><div v-for="a in rows" :key="a.id" class="table-row audit-row"><strong>{{a.actorName}}</strong><span>{{a.action}}</span><span>{{a.entityType}}</span><small>{{a.details}}</small><time>{{date(a.createdAt)}}</time></div><p v-if="!rows.length" class="empty-inline">{{t('noData')}}</p></TableFrame></template>
    <template v-else-if="page==='profile'">
      <section v-if="selected" class="card profile-card profile-page-card">
        <div class="profile-identity">
          <div class="profile-photo-frame" :class="(selected.photoShape||'CIRCLE').toLowerCase()">
            <img v-if="profilePhotoPreview||selected.photoUrl" :src="profilePhotoPreview||assetUrl(selected.photoUrl)" :alt="selected.fullName" @error="$event.target.hidden=true">
            <span v-else>{{selected.firstName?.[0]}}{{selected.lastName?.[0]}}</span>
          </div>
          <div class="profile-identity-copy"><small>{{t('profileTitle')}}</small><h2>{{selected.fullName}}</h2><p>{{selected.phone}} · {{selected.roleName}}</p></div>
        </div>
        <section class="profile-photo-section" :aria-label="t('photo')">
          <div><h3>{{t('photo')}}</h3><p>{{t('profilePhotoHint')}}</p></div>
          <div class="profile-photo-actions">
            <FileUploadField :label="t('photo')" :choose-label="t('choosePhoto')" :help="t('fileUploadHint')" :file-name="profilePhotoFile?.name" accept="image/png,image/jpeg,image/webp" @change="selectProfilePhoto" />
            <select v-model="selected.photoShape" :aria-label="t('photoShape')"><option value="CIRCLE">{{t('circle')}}</option><option value="SQUARE">{{t('square')}}</option></select>
            <button v-if="profilePhotoChanged" class="primary-button" type="button" :disabled="profilePhotoSaving" @click="saveProfilePhoto">{{profilePhotoSaving?t('loading'):t('saveProfilePhoto')}}</button>
          </div>
        </section>
        <div class="preference-row"><span>{{t('changeLanguage')}}</span><button class="small-button" @click="app.setLang('fr')">FR</button><button class="small-button" @click="app.setLang('en')">EN</button></div>
        <div class="preference-row"><span>{{t('theme')}}</span><button class="small-button" @click="app.setTheme('light')">{{t('light')}}</button><button class="small-button" @click="app.setTheme('dark')">{{t('dark')}}</button></div>
        <form class="password-change" @submit.prevent="changePassword"><h3>{{t('changePassword')}}</h3><input v-model="passwords.currentPassword" type="password" :placeholder="t('currentPassword')"><input v-model="passwords.newPassword" type="password" :placeholder="t('newPassword')"><input v-model="passwords.confirm" type="password" :placeholder="t('confirmPassword')"><button class="primary-button">{{t('save')}}</button></form>
      </section>
    </template>

    <Transition name="modal"><ModalShell v-if="showForm" @close="showForm=false;approvalRequest=null;eventEditMode=false;editingMemberPermissions=false;editingBureauPosition=false"><form class="modal-card" @submit.prevent="page==='eventDetail'&&!eventEditMode?submitContribution():submitForm()"><button type="button" class="modal-close" @click="showForm=false;approvalRequest=null;eventEditMode=false;editingMemberPermissions=false;editingBureauPosition=false">×</button><h2>{{approvalRequest?t('approve'):eventEditMode?t('edit'):modalTitle}}</h2>
      <template v-if="approvalRequest"><p>{{approvalRequest.memberName}} · {{approvalRequest.typeName}}</p><label>{{t('closing')}}<input v-model="form.closingDate" type="date"></label></template>
      <template v-else-if="editingMemberPermissions"><p>{{selected?.fullName}} · {{selected?.roleName}}</p><p class="form-hint">{{t('memberPermissionsHint')}}</p><div class="permission-picker"><label v-for="permission in typeList" :key="permission.code" class="checkbox-label"><input v-model="form.permissions" type="checkbox" :value="permission.code">{{app.lang==='fr'?permission.labelFr:permission.labelEn}}</label></div></template>
      <template v-else-if="editingBureauPosition"><p>{{selected?.fullName}}</p><label>{{t('boardRole')}}<select v-model="form.position" required><option v-for="p in boardPositions" :key="p" :value="p">{{p.replaceAll('_',' ')}}</option></select></label></template>
      <template v-else-if="page==='eventDetail'&&eventEditMode"><label>{{t('description')}}<textarea v-model="form.description"></textarea></label><label>{{t('closing')}}<input v-model="form.closingDate" type="date"></label><label>{{t('targetAmount')}}<input v-model="form.targetAmount" type="number" min="0"></label><FileUploadField :label="t('document')" :choose-label="t('chooseFile')" :help="t('fileUploadHint')" :file-name="documentFile?.name" accept=".pdf,.doc,.docx,.xls,.xlsx,image/png,image/jpeg,image/webp" @change="uploadDocument" /><img v-if="documentPreview" :src="documentPreview" :alt="t('document')" class="image-preview square" /></template>
      <template v-else-if="page==='members'"><div class="form-grid"><label>{{t('firstName')}}<input v-model="form.firstName" required></label><label>{{t('lastName')}}<input v-model="form.lastName" required></label><label>{{t('phone')}}<input v-model="form.phone" required></label><label>{{t('city')}}<input v-model="form.city" required></label><label>{{t('quarter')}}<input v-model="form.quarter"></label><label>{{t('email')}}<input v-model="form.email" type="email" :required="!editId"></label></div><label v-if="!editId">{{t('password')}}<input v-model="form.password" type="password"></label><label v-if="editId&&app.can('MEMBER_THRESHOLD_EDIT')">{{t('thresholdOverride')}}<input v-model.number="form.requiredAssistancesOverride" type="number" min="0"></label><FileUploadField :label="t('photo')" :choose-label="t('choosePhoto')" :help="t('fileUploadHint')" :file-name="proofFile?.name" accept="image/png,image/jpeg,image/webp" @change="uploadImage" /><label v-if="!editId">{{t('photoShape')}}<select v-model="form.photoShape"><option value="CIRCLE">{{t('circle')}}</option><option value="SQUARE">{{t('square')}}</option></select></label><img v-if="proofPreview" :src="proofPreview" class="image-preview" :class="(form.photoShape||'CIRCLE').toLowerCase()"></template>
      <template v-else-if="page==='assistances'"><label>{{t('type')}}<select v-model="form.typeId" required><option v-for="ty in typeList" :key="ty.id" :value="ty.id">{{ty.name}}</option></select></label><label>{{t('beneficiary')}}<select v-model="form.beneficiaryId" required><option v-for="m in memberList" :key="m.id" :value="m.id">{{m.fullName}} · {{m.phone}}</option></select></label><label>{{t('reason')}}<textarea v-model="form.description" required></textarea></label><label>{{t('closing')}}<input v-model="form.closingDate" type="date"></label><label>{{t('targetAmount')}}<input v-model="form.targetAmount" type="number" min="0"></label><label v-if="app.can('REQUEST_OVERRIDE_ELIGIBILITY')" class="checkbox-label"><input v-model="form.overrideEligibility" type="checkbox">{{t('overrideEligibility')}}</label><FileUploadField :label="t('document')" :choose-label="t('chooseFile')" :help="t('fileUploadHint')" :file-name="documentFile?.name" accept=".pdf,.doc,.docx,.xls,.xlsx,image/png,image/jpeg,image/webp" @change="uploadDocument" /><img v-if="documentPreview" :src="documentPreview" :alt="t('document')" class="image-preview square" /></template>
      <template v-else-if="page==='requests'"><label>{{t('type')}}<select v-model="form.typeId" required><option v-for="ty in typeList" :key="ty.id" :value="ty.id">{{ty.name}}</option></select></label><label>{{t('reason')}}<textarea v-model="form.reason" required></textarea></label><FileUploadField :label="t('document')" :choose-label="t('chooseFile')" :help="t('fileUploadHint')" :file-name="documentFile?.name" accept=".pdf,.doc,.docx,.xls,.xlsx,image/png,image/jpeg,image/webp" @change="uploadDocument" /><img v-if="documentPreview" :src="documentPreview" :alt="t('document')" class="image-preview square" /></template>
      <template v-else-if="page==='eventDetail'"><label>{{t('amount')}} ({{app.settings?.currency||'FCFA'}})<input v-model="form.amount" type="number" :min="app.settings?.minContributionAmount??0" :step="1" required></label><label>{{t('method')}}<select v-model="form.method"><option value="CASH">{{t('cash')}}</option><option value="MOBILE_MONEY">{{t('mobileMoney')}}</option><option value="TRANSFER">{{t('transfer')}}</option></select></label><label>{{t('note')}}<textarea v-model="form.note"></textarea></label><FileUploadField :label="t('proof')" :choose-label="t('chooseFile')" :help="t('proofUploadHint')" :file-name="proofFile?.name" accept="image/png,image/jpeg,image/webp" @change="uploadImage" /><img v-if="proofPreview" :src="proofPreview" class="image-preview square"></template>
      <template v-else-if="page==='types'"><label>{{t('type')}}<input v-model="form.name" required></label><label>{{t('icon')}}<input v-model="form.icon"></label></template>
      <template v-else-if="page==='roles'"><label>{{t('code')}}<input v-model="form.code" required></label><label>{{t('role')}}<input v-model="form.name" required></label><p v-if="editId" class="form-hint">{{t('rolePermissionsHint')}}</p><div class="permission-picker"><label v-for="permission in typeList" :key="permission.code" class="checkbox-label"><input v-model="form.permissions" type="checkbox" :value="permission.code">{{app.lang==='fr'?permission.labelFr:permission.labelEn}}</label></div></template>
      <template v-else-if="page==='board'"><label>{{t('membersTotal')}}<select v-model="form.memberId" required><option value="">{{t('chooseMember')}}</option><option v-for="m in memberList.filter(x=>!x.bureauPosition||x.id===editId)" :key="m.id" :value="m.id">{{m.fullName}}</option></select></label><label v-if="!editId">{{t('boardRole')}}<select v-model="form.position"><option v-for="p in boardPositions" :key="p" :value="p">{{p.replaceAll('_',' ')}}</option></select></label><p v-else class="form-hint">{{t('boardReplacementHint')}}</p></template>
      <template v-else-if="page==='groups'"><label>{{t('group')}}<input v-model="form.name" required></label><label>{{t('city')}}<input v-model="form.city"></label><label>{{t('description')}}<textarea v-model="form.description"></textarea></label><div class="form-grid"><label>{{t('phone')}}<input v-model="form.contactPhone"></label><label>{{t('email')}}<input v-model="form.contactEmail" type="email"></label><label>{{t('currency')}}<input v-model="form.currency"></label><label>{{t('minimumAssistances')}}<input v-model.number="form.minAssistancesRequired" type="number" min="0"></label><label>{{t('primaryColor')}}<input v-model="form.primaryColor" type="color"></label><label>{{t('accentColor')}}<input v-model="form.accentColor" type="color"></label></div><FileUploadField :label="t('photo')" :choose-label="t('choosePhoto')" :help="t('fileUploadHint')" :file-name="proofFile?.name" accept="image/png,image/jpeg,image/webp" @change="uploadImage" /><img v-if="proofPreview" :src="proofPreview" class="image-preview square"><template v-if="!editId"><h3>{{t('principalAdmin')}}</h3><div class="form-grid"><label>{{t('firstName')}}<input v-model="form.firstName" required></label><label>{{t('lastName')}}<input v-model="form.lastName" required></label><label>{{t('phone')}}<input v-model="form.phone" required></label><label>{{t('email')}}<input v-model="form.email" type="email" required></label><label>{{t('password')}}<input v-model="form.password" type="password"></label></div></template></template>
      <template v-else-if="page==='assignments'"><label>{{t('membersTotal')}}<select v-model="form.memberId"><option v-for="m in memberList" :key="m.id" :value="m.id">{{m.fullName}}</option></select></label><label>{{t('role')}}<select v-model="form.roleId"><option v-for="r in roleList" :key="r.id" :value="r.id">{{r.name}}</option></select></label></template>
      <p v-if="error" class="form-error">{{error}}</p><div class="modal-actions"><button type="button" class="secondary-button" @click="showForm=false;approvalRequest=null;eventEditMode=false;editingMemberPermissions=false;editingBureauPosition=false">{{t('cancel')}}</button><button class="primary-button" :disabled="saving">{{saving?t('loading'):approvalRequest?t('approve'):eventEditMode?t('save'):page==='eventDetail'?t('saveContribution'):t('save')}}</button></div>
    </form></ModalShell></Transition>
  </section>
</template>



